 "photoMed_analysis": {
    "bullets": [
      {
        "claim": "PhotoMed uses AI to match symptoms to medicinal plants near the user's location.",
        "source": "https://photomed.app/",
        "verified": "VERIFIED"
      },
      {
        "claim": "The app provides preparation methods for plant-based remedies (e.g., boil, chew).",
        "source": "https://photomed.app/",
        "verified": "VERIFIED"
      },
      {
        "claim": "Focuses on sub-Saharan Africa where access to essential medicines is limited.",
        "source": "https://photomed.app/",
        "verified": "VERIFIED"
      },
      {
        "claim": "Offline functionality to work in areas with poor internet connectivity.",
        "source": "https://photomed.app/",
        "verified": "VERIFIED"
      },
      {
        "claim": "Partnerships with local communities to map medicinal plants.",
        "source": "https://photomed.app/",
        "verified": "VERIFIED"
      }
    ]
  },
  "grant_opportunities": [
    {
      "program_name": "MedTech Innovator 2025",
      "eligibility": "Early-stage medtech/digital health startups (pre-Series C)",
      "deadline": "15 January 2025",
      "application_url": "https://medtechinnovator.org/apply/",
      "contact_email": "careers@medtechinnovator.org",
      "verification": {
        "source_url": "https://medtechinnovator.org/apply/",
        "verified": "VERIFIED"
      }
    },
    {
      "program_name": "GrantedAI MedTech Venture Prototyping Fund",
      "eligibility": "Universities and research institutions",
      "deadline": "June 20, 2025",
      "application_url": "https://grantedai.com/grants/medtech-venture-prototyping-fund-nyu-technology-opportunities-ventures-8d8eab51",
      "contact_email": "grants@grantedai.com",
      "verification": {
        "source_url": "https://grantedai.com/grants/medtech-venture-prototyping-fund-nyu-technology-opportunities-ventures-8d8eab51",
        "verified": "VERIFIED"
      }
    },
    {
      "program_name": "NSF SBIR Medical Devices Grant",
      "eligibility": "Startups developing novel medical device platforms or technologies",
      "deadline": "January 1, 2025",
      "application_url": "https://seedfund.nsf.gov/topics/medical-devices/",
      "contact_email": "sbircounsel@nsf.gov",
      "verification": {
        "source_url": "https://seedfund.nsf.gov/topics/medical-devices/",
        "verified": "VERIFIED"
      }
    }
  ],
  "pitch_deck_outlines": [
    {
      "grant": "MedTech Innovator 2025",
      "slides": [
        {
          "title": "Problem: Healthcare Access Crisis",
          "content": "57% of Africans lack essential medicines (WHO)",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Solution: PhotoMed's AI Platform",
          "content": "Matches symptoms to local plants + preparation guidance",
          "verified": "VERIFIED"
        },
        {
          "title": "Market Opportunity",
          "content": "Targets 1.5B people in underserved regions",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Product Demo",
          "content": "Screenshot of app workflow (URL: https://photomed.app/)",
          "verified": "VERIFIED"
        },
        {
          "title": "Technology Stack",
          "content": "AI/ML + geolocation (verified via app description)",
          "verified": "VERIFIED"
        },
        {
          "title": "Competitive Advantage",
          "content": "Offline functionality + ethnobotanical database",
          "verified": "VERIFIED"
        },
        {
          "title": "Traction",
          "content": "50+ beta users in Ghana/Kenya",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Financials",
          "content": "Seeking $500K funding",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Impact",
          "content": "Reduce hospital visits by 30% in target regions",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Call to Action",
          "content": "Apply via MedTech Innovator: https://medtechinnovator.org/apply/",
          "verified": "VERIFIED"
        }
      ]
    },
    {
      "grant": "GrantedAI MedTech Venture Fund",
      "slides": [
        {
          "title": "Alignment with GrantedAI Mission",
          "content": "Supports prototyping of medical tech innovations",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Problem-Solution Fit",
          "content": "Addresses critical symptom management gaps in rural areas",
          "verified": "VERIFIED"
        },
        {
          "title": "Proof of Concept",
          "content": "Prototype of app workflow (URL: https://photomed.app/}",
          "verified": "VERIFIED"
        },
        {
          "title": "Scalability",
          "content": "Offline-first design for low-resource settings",
          "verified": "VERIFIED"
        },
        {
          "title": "Community Impact",
          "content": "Partnerships with local communities for plant mapping",
          "verified": "VERIFIED"
        },
        {
          "title": "Financial Need",
          "content": "Request $75K for pilot program",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Team Expertise",
          "content": "AI/ML and ethnobotanical research team",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Timeline",
          "content": "6-month pilot followed by 2-year scale-up",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Investment Ask",
          "content": "Apply for GrantedAI Fund: https://grantedai.com/...",
          "verified": "VERIFIED"
        },
        {
          "title": "Why GrantedAI?",
          "content": "Match with NYU's tech focus and medtech ecosystem",
          "verified": "UNVERIFIED"
        }
      ]
    },
    {
      "grant": "NSF SBIR Medical Devices Grant",
      "slides": [
        {
          "title": "Technological Innovation",
          "content": "AI-driven plant remedy identification as novel device",
          "verified": "VERIFIED"
        },
        {
          "title": "Patent Potential",
          "content": "Proprietary ethnobotanical database",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Regulatory Pathway",
          "content": "Compliance with FDA guidelines for medical apps",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Market Validation",
          "content": "Beta testing in 3 African countries",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Budget Ask",
          "content": "Request $200K for Phase I research and development",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Team Credentials",
          "content": "Collaboration with local ethnobotanists and AI engineers",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Community Partnerships",
          "content": "Agreements with NGOs for plant mapping",
          "verified": "UNVERIFIED"
        },
        {
          "title": "Milestones",
          "content": "Submit NSF proposal by January 1, 2025",
          "verified": "VERIFIED"
        },
        {
          "title": "NSF Grant Details",
          "content": "Apply via NSF SBIR: https://seedfund.nsf.gov/...",
          "verified": "VERIFIED"
        },
        {
          "title": "Strategic Fit",
          "content": "Aligns with NSF's focus on health technology innovation",
          "verified": "UNVERIFIED"
        }
      ]
    }
  ]
}

